    "source": "// --- inlined from _shared/classify.ts by tools/bundle-provision.py ---\n/**\n * User-agent triage for inbound pixel hits.\n *\n * The thing to internalise: on Gmail-to-Gmail mail you are almost never talking\n * to the recipient. Google fetches every image through its own proxy, so the UA\n * and IP you see belong to Google. `proxy` records who we think fetched it;\n * `prefetch` marks fetches we believe no human triggered at all.\n */\n\ninterface AgentVerdict {\n  proxy: string | null;\n  prefetch: boolean;\n}\n\nconst SCANNERS = [\n  \"proofpoint\",\n  \"barracuda\",\n  \"mimecast\",\n  \"symantec\",\n  \"forcepoint\",\n  \"trendmicro\",\n  \"sophos\",\n  \"messagelabs\",\n  \"cloudmark\",\n  \"urldefense\",\n  \"virustotal\",\n];\n\nconst ROBOTS = [\n  \"bot\",\n  \"crawler\",\n  \"spider\",\n  \"slurp\",\n  \"headlesschrome\",\n  \"python-requests\",\n  \"go-http-client\",\n  \"curl/\",\n  \"wget\",\n  \"libwww\",\n];\n\nfunction classifyAgent(userAgent: string | null): AgentVerdict {\n  const ua = (userAgent ?? \"\").toLowerCase();\n  if (!ua) return { proxy: null, prefetch: false };\n\n  // Gmail. Expect this on the overwhelming majority of hits.\n  if (ua.includes(\"googleimageproxy\") || ua.includes(\"ggpht.com\")) {\n    return { proxy: \"google\", prefetch: false };\n  }\n\n  if (ua.includes(\"yahoomailproxy\")) return { proxy: \"yahoo\", prefetch: false };\n\n  if (\n    ua.includes(\"bingpreview\") ||\n    ua.includes(\"skypeuripreview\") ||\n    ua.includes(\"microsoft office\") ||\n    ua.includes(\"ms-office\")\n  ) {\n    return { proxy: \"microsoft\", prefetch: false };\n  }\n\n  // Corporate mail gateways detonate every image and link on arrival, long\n  // before anyone reads the message.\n  for (const s of SCANNERS) {\n    if (ua.includes(s)) return { proxy: \"scanner\", prefetch: true };\n  }\n  for (const r of ROBOTS) {\n    if (ua.includes(r)) return { proxy: \"scanner\", prefetch: true };\n  }\n\n  // Apple Mail Privacy Protection, best effort. MPP fetches through a relay\n  // using a URLSession-style agent: a macOS AppleWebKit string with neither a\n  // `Version/` nor a `Safari/` token, which a real Safari always carries. This\n  // is a heuristic and it will miss cases — see docs/ACCURACY.md.\n  if (\n    ua.includes(\"mac os x\") &&\n    ua.includes(\"applewebkit\") &&\n    !ua.includes(\"version/\") &&\n    !ua.includes(\"safari/\")\n  ) {\n    return { proxy: \"apple\", prefetch: true };\n  }\n\n  return { proxy: null, prefetch: false };\n}\n\n/** First entry of X-Forwarded-For; the rest are downstream hops we don't trust. */\nfunction clientIp(req: Request): string | null {\n  const xff = req.headers.get(\"x-forwarded-for\");\n  if (xff) {\n    const first = xff.split(\",\")[0].trim();\n    if (first) return first;\n  }\n  return req.headers.get(\"cf-connecting-ip\") ?? req.headers.get(\"x-real-ip\");\n}\n\n/** Pull the token out of `/px/<token>.gif`, `/r/<token>`, and friends. */\nfunction tokenFromPath(url: string, functionName: string): string | null {\n  const segments = new URL(url).pathname.split(\"/\").filter(Boolean);\n  const last = segments[segments.length - 1] ?? \"\";\n  if (!last || last === functionName) return null;\n  const token = last.replace(/\\.(gif|png|jpe?g|webp)$/i, \"\");\n  return /^[A-Za-z0-9_-]{16,64}$/.test(token) ? token : null;\n}\n\n// --- end inlined helpers ---\n\n/**\n * GET /functions/v1/px/<token>.gif\n *\n * Serves a 1x1 transparent GIF and records the fetch. Two rules govern this\n * file: it always returns a valid image, whatever goes wrong, and it never\n * makes the caller wait on the database.\n *\n * Deploy with --no-verify-jwt (or leave verify_jwt = false in config.toml).\n */\n\n// 42-byte 1x1 transparent GIF.\nconst PIXEL = Uint8Array.from(\n  atob(\"R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7\"),\n  (c) => c.charCodeAt(0),\n);\n\nconst SUPABASE_URL = Deno.env.get(\"SUPABASE_URL\")!;\nconst SERVICE_KEY = Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\")!;\n\nconst HEADERS: HeadersInit = {\n  \"content-type\": \"image/gif\",\n  \"content-length\": String(PIXEL.byteLength),\n  // Gmail, Apple and Outlook all cache proxied images hard. Without these you\n  // record the first open of a message and then silence for ever after.\n  \"cache-control\": \"no-store, no-cache, must-revalidate, private, max-age=0\",\n  \"pragma\": \"no-cache\",\n  \"expires\": \"0\",\n  \"x-content-type-options\": \"nosniff\",\n};\n\nconst image = (body: BodyInit | null) =>\n  new Response(body, { status: 200, headers: HEADERS });\n\nasync function record(token: string, req: Request): Promise<void> {\n  const userAgent = req.headers.get(\"user-agent\");\n  const { proxy, prefetch } = classifyAgent(userAgent);\n\n  const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/record_open`, {\n    method: \"POST\",\n    headers: {\n      \"content-type\": \"application/json\",\n      apikey: SERVICE_KEY,\n      authorization: `Bearer ${SERVICE_KEY}`,\n    },\n    body: JSON.stringify({\n      p_token: token,\n      p_user_agent: userAgent,\n      p_ip: clientIp(req),\n      p_proxy: proxy,\n      p_ua_prefetch: prefetch,\n    }),\n  });\n\n  if (!res.ok) console.error(\"record_open failed\", res.status, await res.text());\n}\n\nDeno.serve(async (req: Request) => {\n  const body = req.method === \"HEAD\" ? null : PIXEL;\n\n  const token = tokenFromPath(req.url, \"px\");\n  if (!token || (req.method !== \"GET\" && req.method !== \"HEAD\")) return image(body);\n\n  const task = record(token, req).catch((err) => console.error(\"record_open\", err));\n\n  // Hand back the image now and finish the insert after the response has gone\n  // out. Falls back to awaiting where waitUntil isn't offered, since a dropped\n  // isolate would lose the open entirely.\n  // deno-lint-ignore no-explicit-any\n  const waitUntil = (globalThis as any).EdgeRuntime?.waitUntil;\n  if (typeof waitUntil === \"function\") {\n    // deno-lint-ignore no-explicit-any\n    waitUntil.call((globalThis as any).EdgeRuntime, task);\n  } else {\n    await task;\n  }\n\n  return image(body);\n});\n",
